class ILocalizationProvider {
  translate(key, locale) { throw new Error('Not implemented') }
}
class StaticJsonProvider extends ILocalizationProvider {
  constructor(dict) { this.dict = dict; }
  translate(key, locale) { return (this.dict[locale] && this.dict[locale][key]) || key; }
}
class ProviderRegistry {
  constructor() { this.map = new Map(); }
  register(locale, provider) { this.map.set(locale, provider); }
  resolve(locale) { return this.map.get(locale) || new StaticJsonProvider({ 'en-GB': { 'hello': 'Hello' } }); }
